-- Add the editable club page without replacing existing editorial content or navigation.
INSERT INTO "StorefrontPage" ("slug", "title", "eyebrow", "lead", "seoDescription", "blocks", "updatedAt") VALUES
('club', 'Любимые материалы. Больше возможностей.', 'SARKISIAN CLUB', 'Ваш клуб профессиональных покупок: бонусы, понятный баланс и вся история участия в одном личном кабинете.', 'SARKISIAN CLUB: бонусы за покупки, уровни участия, баланс и история начислений. Узнайте, как присоединиться к программе.', $$[
 {"id":"rewards","title":"Покупки, которые возвращаются бонусами","body":"Выбирайте материалы и инструменты для своей работы. За покупки, подходящие под условия программы, начисляются бонусы для следующих заказов.\nРазмер начислений и возможность списания определяются действующими правилами программы. Проверяйте доступные условия в личном кабинете и при оформлении заказа."},
 {"id":"balance","title":"Всё о бонусах — без лишних вопросов","body":"В разделе «Бонусы» личного кабинета доступны баланс и история операций. Вы можете посмотреть начисления и списания, а также понять, как менялся ваш баланс.\nБонусы не являются денежными средствами и не могут быть выведены или обменены на деньги."},
 {"id":"levels","title":"Ваш уровень участия","body":"В личном кабинете отображаются текущий уровень и прогресс до следующего. Условия уровней задаются правилами программы и могут отличаться.\nАктуальные условия важнее любых примеров на сайте: бонусная карта на этой странице иллюстрирует оформление, а не показывает ваш персональный баланс."},
 {"id":"joining","title":"Начните с регистрации","body":"Нажмите «Вступить в клуб» и создайте аккаунт. Если аккаунт уже есть, войдите в него: не нужно регистрироваться повторно.\nОформляйте покупки с одним аккаунтом, чтобы заказы и бонусные операции сохранялись в общей истории. Личные данные можно проверить в настройках кабинета."},
 {"id":"rules","title":"Понятные условия использования","body":"Доступность начислений, максимальное списание и срок действия бонусов определяются действующими настройками программы. Не все заказы и товары могут участвовать в начислениях.\nПри отмене или возврате заказа связанные начисления могут быть скорректированы. Перед оплатой проверьте итоговую сумму и условия использования бонусов."},
 {"id":"support","title":"Мы на связи","body":"Если возник вопрос по начислению или балансу, свяжитесь с командой магазина через страницу «Контакты». Укажите номер заказа и адрес электронной почты своего аккаунта, чтобы мы могли разобраться быстрее.\nНикому не сообщайте свой пароль или коды подтверждения — они не нужны для проверки бонусов."}
]$$::jsonb, CURRENT_TIMESTAMP)
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "StorefrontMenuItem" ("id", "label", "url", "sortOrder", "updatedAt")
SELECT 'd90916a0-0000-4000-8000-000000000004', 'О клубе', '/club', COALESCE(MAX("sortOrder"), -1) + 1, CURRENT_TIMESTAMP
FROM "StorefrontMenuItem"
WHERE NOT EXISTS (SELECT 1 FROM "StorefrontMenuItem" WHERE "url" = '/club')
HAVING NOT EXISTS (SELECT 1 FROM "StorefrontMenuItem" WHERE "url" = '/club')
ON CONFLICT ("id") DO NOTHING;
